mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RN, A.* FROM ( SELECT N.NOTICE_NO, N.NOTICE_TITLE, N.NOTICE_CONTENT, N.CREATE_DATE, N.MEMBER_NO, N.STATUS, I.CHANGE_NAME AS THUMBNAIL_URL FROM TB_NOTICE N LEFT JOIN TB_NOTICE_IMG I ON N.NOTICE_NO = I.NOTICE_NO AND I.STATUS = 'Y' AND I.IS_THUMBNAIL = 'Y'
N.STATUS = 'Y'
ORDER BY N.NOTICE_NO DESC ) A ) WHERE RN BETWEEN #{startRow} AND #{endRow}

mapper.update:
UPDATE TB_NOTICE
SET NOTICE_TITLE = #{noticeTitle},
    NOTICE_CONTENT = #{noticeContent}
WHERE NOTICE_NO = #{noticeNo}
  AND STATUS = 'Y'

UPDATE TB_NOTICE
SET STATUS = 'N'
WHERE NOTICE_NO = #{noticeNo}

UPDATE TB_NOTICE_IMG
SET STATUS = 'N'
WHERE NOTICE_NO = #{noticeNo}
